export const CARD_IMAGE_SIZES = Object.freeze({table: Object.freeze({width:560,height:960}),detail:Object.freeze({width:1050,height:1800})});
/** baseURL must point to the copied package assets directory, ending in /. */
export function getCardImageURL(id, {size = 'table', baseURL} = {}) {
  if (!Number.isInteger(id) || !Object.hasOwn(CARD_FILES,id)) throw new RangeError('Unknown card id');
  if (!Object.hasOwn(CARD_IMAGE_SIZES,size)) throw new RangeError('Unknown image size');
  const base = baseURL === undefined ? new URL(/* @vite-ignore */ '../assets/', import.meta.url) : new URL(baseURL);
  if (!base.pathname.endsWith('/')) throw new TypeError('baseURL must end in /');
  return new URL(`${size}/${CARD_FILES[id]}`, base).href;
}
